#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: ms-ranking sealed secrets (ticket 1.4, RK-18b).
# Aucune valeur n'est ecrite en clair dans le depot ni dans un .env : les valeurs vivent dans un
# repertoire temporaire (chmod 700) supprime a la sortie, seul le SealedSecret chiffre est ecrit.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=4

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
DB_SEALED="$REPO_ROOT/apps/overlays/prod/shared-infra/db-sealed-secret.yaml"
RANKING_DIR="$REPO_ROOT/apps/overlays/prod/ms-ranking"
RANKING_SEALED="$RANKING_DIR/ranking-sealed-secret.yaml"
RANKING_KUSTOMIZATION="$RANKING_DIR/kustomization.yaml"
NAMESPACE="prod"
CONTROLLER_NAME="sealed-secrets"
CONTROLLER_NAMESPACE="kube-system"

WORKDIR="$(mktemp -d)"
chmod 700 "$WORKDIR"
trap 'rm -rf "$WORKDIR"' EXIT

# rand_alnum N : N caracteres alphanumeriques aleatoires (CSPRNG via openssl).
rand_alnum() {
  local n="$1" out=""
  while [[ ${#out} -lt $n ]]; do
    out+=$(openssl rand -base64 48 | tr -dc 'A-Za-z0-9')
  done
  printf '%s' "${out:0:$n}"
}

banner "ms-ranking : secrets scelles (db-secrets, ranking-secrets)"

stage "Prerequis"
say "Ce wizard scelle trois valeurs pour le namespace '$NAMESPACE' du cluster K3s."
say "  - ms-ranking-password : mot de passe PostgreSQL, ajoute au SealedSecret db-secrets existant"
say "  - RANKING_LOCATION_KEY : 32 caracteres aleatoires (32 octets utilises tels quels par AES-256-GCM)"
say "  - TYPESAFE_API_KEY : cle Jev (optionnelle pour l'instant, le scoreur n'est pas branche)"
note "Rien n'est ecrit en clair dans Git. Les valeurs passent par $WORKDIR (supprime a la sortie)."
for bin in kubeseal kubectl openssl; do
  if command -v "$bin" >/dev/null 2>&1; then
    printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$bin"
  else
    warn "$bin est introuvable : installe-le puis relance ce wizard"
    exit 1
  fi
done
[[ -f "$DB_SEALED" ]] || { warn "introuvable : $DB_SEALED"; exit 1; }
[[ -f "$RANKING_KUSTOMIZATION" ]] || { warn "introuvable : $RANKING_KUSTOMIZATION"; exit 1; }
say ""
say "Verification de l'acces au cluster (lecture seule) :"
if kubectl -n "$NAMESPACE" get secret auth-certs >/dev/null 2>&1; then
  printf '  %s✓%s secret auth-certs present dans %s (cles internal.key / internal.pub montees par ms-ranking et worker-ranking)\n' "$GREEN" "$RESET" "$NAMESPACE"
else
  warn "secret auth-certs introuvable ou cluster inaccessible : ms-ranking et worker-ranking en ont besoin (certs/internal.*)."
  confirm "Continuer quand meme ?" || exit 1
fi
if kubectl -n "$CONTROLLER_NAMESPACE" get deploy "$CONTROLLER_NAME" >/dev/null 2>&1; then
  printf '  %s✓%s controleur %s joignable\n' "$GREEN" "$RESET" "$CONTROLLER_NAME"
else
  warn "controleur $CONTROLLER_NAME introuvable dans $CONTROLLER_NAMESPACE : kubeseal ne pourra pas chiffrer"
  confirm "Continuer quand meme ?" || exit 1
fi
pause "Entree pour continuer"

stage "Mot de passe PostgreSQL de ms-ranking (db-secrets)"
if grep -q '^    ms-ranking-password:' "$DB_SEALED"; then
  warn "ms-ranking-password existe deja dans $DB_SEALED"
  say "Le regenerer ne change PAS le mot de passe de l'utilisateur deja cree dans PostgreSQL : a ne faire que sur une base neuve."
  confirm "Le regenerer quand meme ?" || SKIP_DB=1
fi
if [[ -z "${SKIP_DB:-}" ]]; then
  say "Generation d'un mot de passe aleatoire de 32 caracteres, scellement, fusion dans le SealedSecret db-secrets."
  DB_PASSWORD_VALUE="$(rand_alnum 32)"
  printf '%s' "$DB_PASSWORD_VALUE" > "$WORKDIR/ms-ranking-password"
  unset DB_PASSWORD_VALUE
  kubectl create secret generic db-secrets \
    --namespace "$NAMESPACE" \
    --from-file=ms-ranking-password="$WORKDIR/ms-ranking-password" \
    --dry-run=client -o yaml \
    | kubeseal --controller-name="$CONTROLLER_NAME" --controller-namespace="$CONTROLLER_NAMESPACE" \
        --format=yaml --merge-into "$DB_SEALED"
  rm -f "$WORKDIR/ms-ranking-password"
  printf '  %s✓%s ms-ranking-password fusionne dans %s\n' "$GREEN" "$RESET" "$DB_SEALED"
  note "Le mot de passe en clair n'est jamais affiche ni conserve : il n'existe que dans le SealedSecret."
fi
pause "Entree pour continuer"

stage "Secret ranking-secrets (RANKING_LOCATION_KEY, TYPESAFE_API_KEY)"
if [[ -f "$RANKING_SEALED" ]]; then
  warn "$RANKING_SEALED existe deja"
  say "Regenerer RANKING_LOCATION_KEY rend illisibles les positions deja chiffrees en base."
  confirm "Ecraser quand meme ?" || SKIP_RANKING=1
fi
if [[ -z "${SKIP_RANKING:-}" ]]; then
  say "RANKING_LOCATION_KEY : generee automatiquement (32 caracteres alphanumeriques, CSPRNG)."
  printf '%s' "$(rand_alnum 32)" > "$WORKDIR/RANKING_LOCATION_KEY"
  say ""
  say "TYPESAFE_API_KEY : colle la cle Jev, ou laisse vide pour l'ajouter plus tard"
  note "Condition avant d'activer Jev : politique de conservation de TypeSafe AI obtenue (decision 33 de 13-decisions-v1.md)."
  ask_secret TYPESAFE_API_KEY_INPUT "Cle TypeSafe AI (Entree pour passer) :"
  CREATE_ARGS=(--from-file=RANKING_LOCATION_KEY="$WORKDIR/RANKING_LOCATION_KEY")
  if [[ -n "${TYPESAFE_API_KEY_INPUT:-}" ]]; then
    printf '%s' "$TYPESAFE_API_KEY_INPUT" > "$WORKDIR/TYPESAFE_API_KEY"
    CREATE_ARGS+=(--from-file=TYPESAFE_API_KEY="$WORKDIR/TYPESAFE_API_KEY")
  else
    SKIPPED+=("TYPESAFE_API_KEY (reexecuter ce wizard pour l'ajouter ; le deployment la lit en optional: true)")
  fi
  unset TYPESAFE_API_KEY_INPUT
  kubectl create secret generic ranking-secrets \
    --namespace "$NAMESPACE" "${CREATE_ARGS[@]}" \
    --dry-run=client -o yaml \
    | kubeseal --controller-name="$CONTROLLER_NAME" --controller-namespace="$CONTROLLER_NAMESPACE" \
        --format=yaml > "$RANKING_SEALED"
  rm -f "$WORKDIR/RANKING_LOCATION_KEY" "$WORKDIR/TYPESAFE_API_KEY"
  printf '  %s✓%s SealedSecret ecrit : %s\n' "$GREEN" "$RESET" "$RANKING_SEALED"
fi
if [[ -f "$RANKING_SEALED" ]] && ! grep -q 'ranking-sealed-secret.yaml' "$RANKING_KUSTOMIZATION"; then
  tmp="$WORKDIR/kustomization.yaml"
  awk '{print} /^  - \.\/db-postgres$/ {print "  - ranking-sealed-secret.yaml"}' "$RANKING_KUSTOMIZATION" > "$tmp"
  cat "$tmp" > "$RANKING_KUSTOMIZATION"
  printf '  %s✓%s ranking-sealed-secret.yaml declare dans %s\n' "$GREEN" "$RESET" "$RANKING_KUSTOMIZATION"
fi
note "Sauvegarde la RANKING_LOCATION_KEY hors cluster si tu veux pouvoir restaurer le secret : elle ne se relit pas depuis le SealedSecret."
pause "Entree pour continuer"

stage "Verification et livraison"
say "Controle qu'aucun secret en clair n'est dans l'arbre de travail :"
if grep -rIl -E '^kind: Secret$' "$DB_SEALED" "$RANKING_DIR" 2>/dev/null | grep -q .; then
  warn "un 'kind: Secret' en clair a ete detecte : ne commite pas, supprime-le"
  exit 1
fi
printf '  %s✓%s aucun kind: Secret en clair dans les fichiers touches\n' "$GREEN" "$RESET"
if command -v kustomize >/dev/null 2>&1; then
  if (cd "$REPO_ROOT" && kustomize build apps/overlays/prod --enable-helm >/dev/null); then
    printf '  %s✓%s kustomize build apps/overlays/prod OK\n' "$GREEN" "$RESET"
  else
    warn "kustomize build en echec : corrige avant de commiter"
  fi
fi
say ""
say "Etapes suivantes (a la main) :"
step "git -C $REPO_ROOT status  (attendu : db-sealed-secret.yaml, ms-ranking/kustomization.yaml, ranking-sealed-secret.yaml)"
step "Commiter ces fichiers dans la branche feat/ranking-k8s-manifests, avant le merge (sinon les pods ms-ranking restent en CreateContainerConfigError)"
step "Ne PAS appliquer au cluster avec kubectl : ArgoCD synchronise apres le merge"

finish
